43	// GetInstanceProfile returns the instance profile.
44	func (s *APIV1Service) GetInstanceProfile(ctx context.Context, _ *v1pb.GetInstanceProfileRequest) (*v1pb.InstanceProfile, error) {
45		admin, err := s.GetInstanceAdmin(ctx)
46		if err != nil {
47			return nil, status.Errorf(codes.Internal, "failed to get instance admin: %v", err)
48		}
49	
50		// needs_setup reflects whether the instance has any users at all, which is
51		// the real signal for first-run setup. It is deliberately independent of the
52		// admin lookup: an instance that has lost its admins still has users and must
53		// not be treated as a fresh install.
54		limitOne := 1
55		users, err := s.Store.ListUsers(ctx, &store.FindUser{Limit: &limitOne})
56		if err != nil {
57			return nil, status.Errorf(codes.Internal, "failed to list users: %v", err)
58		}
59	
60		instanceProfile := &v1pb.InstanceProfile{
61			Version:     s.Profile.Version,
62			Demo:        s.Profile.Demo,
63			InstanceUrl: s.Profile.InstanceURL,
64			Admin:       admin, // for display only; may be nil even on a populated instance
65			Commit:      s.Profile.Commit,
66			NeedsSetup:  len(users) == 0,
67		}
68		return instanceProfile, nil
69	}
