28	func (s *APIV1Service) prepareInstanceAISettingForUpdate(ctx context.Context, setting *storepb.InstanceAISetting) error {
29		if setting == nil {
30			return errors.New("AI setting is required")
31		}
32	
33		existing, err := s.Store.GetInstanceAISetting(ctx)
34		if err != nil {
35			return errors.Wrap(err, "failed to get existing AI setting")
36		}
37		existingProviders := map[string]*storepb.AIProviderConfig{}
38		if existing != nil {
39			for _, provider := range existing.Providers {
40				if provider != nil && provider.Id != "" {
41					existingProviders[provider.Id] = provider
42				}
43			}
44		}
45	
46		seenIDs := map[string]bool{}
47		for _, provider := range setting.Providers {
48			if provider == nil {
49				return errors.New("provider cannot be nil")
50			}
51	
52			provider.Id = strings.TrimSpace(provider.Id)
53			if provider.Id == "" {
54				provider.Id = shortuuid.New()
55			}
56			if seenIDs[provider.Id] {
57				return errors.Errorf("duplicate provider ID %q", provider.Id)
58			}
59			seenIDs[provider.Id] = true
60	
61			provider.Title = strings.TrimSpace(provider.Title)
62			if provider.Title == "" {
63				return errors.New("provider title is required")
64			}
65			if provider.Type != storepb.AIProviderType_OPENAI && provider.Type != storepb.AIProviderType_GEMINI {
66				return errors.Errorf("provider %q has unsupported type", provider.Id)
67			}
68	
69			provider.Endpoint = strings.TrimSpace(provider.Endpoint)
70			if provider.Type == storepb.AIProviderType_OPENAI && provider.Endpoint == "" {
71				provider.Endpoint = "https://api.openai.com/v1"
72			}
73			if provider.Type == storepb.AIProviderType_GEMINI && provider.Endpoint == "" {
74				provider.Endpoint = "https://generativelanguage.googleapis.com/v1beta"
75			}
76	
77			if provider.ApiKey == "" {
78				if existingProvider, ok := existingProviders[provider.Id]; ok {
79					provider.ApiKey = existingProvider.ApiKey
80				}
81			}
82			if provider.ApiKey == "" {
83				return errors.Errorf("provider %q API key is required", provider.Id)
84			}
85		}
86	
87		if err := preparePersistedTranscriptionConfig(setting, existing); err != nil {
88			return err
89		}
90		return nil
91	}
