136	func maskAPIKey(apiKey string) string {
137		if apiKey == "" {
138			return ""
139		}
140		if len(apiKey) <= 8 {
141			return "..."
142		}
143		prefixLength := min(4, len(apiKey))
144		return apiKey[:prefixLength] + "..." + apiKey[len(apiKey)-4:]
145	}
