147	func validateInstanceTagsSetting(setting *v1pb.InstanceSetting_TagsSetting) error {
148		if setting == nil {
149			return errors.New("tags setting is required")
150		}
151		for tag, metadata := range setting.Tags {
152			if strings.TrimSpace(tag) == "" {
153				return errors.New("tag key cannot be empty")
154			}
155			if _, err := regexp.Compile(tag); err != nil {
156				return errors.Errorf("tag key %q is not a valid regex pattern: %v", tag, err)
157			}
158			if metadata == nil {
159				return errors.Errorf("tag metadata is required for %q", tag)
160			}
161			if metadata.GetBackgroundColor() != nil {
162				if err := validateInstanceColor(metadata.GetBackgroundColor()); err != nil {
163					return errors.Wrapf(err, "background_color for %q", tag)
164				}
165			}
166		}
167		return nil
168	}
