170	func validateInstanceColor(color *colorpb.Color) error {
171		if err := validateInstanceColorComponent("red", color.GetRed()); err != nil {
172			return err
173		}
174		if err := validateInstanceColorComponent("green", color.GetGreen()); err != nil {
175			return err
176		}
177		if err := validateInstanceColorComponent("blue", color.GetBlue()); err != nil {
178			return err
179		}
180		if alpha := color.GetAlpha(); alpha != nil {
181			if err := validateInstanceColorComponent("alpha", alpha.GetValue()); err != nil {
182				return err
183			}
184		}
185		return nil
186	}
