188	func validateInstanceColorComponent(name string, value float32) error {
189		if math.IsNaN(float64(value)) || math.IsInf(float64(value), 0) {
190			return errors.Errorf("%s must be a finite number", name)
191		}
192		if value < 0 || value > 1 {
193			return errors.Errorf("%s must be between 0 and 1", name)
194		}
195		return nil
196	}
